bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
expected=create-videobot:invoice-only-receipts-9b1075b0
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
test "$(docker inspect "$cid" --format '{{.Image}}')" = "$(docker image inspect "$expected" --format '{{.Id}}')" || exit 42
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
const env=process.env;if(env.VIDEOBOT_DB_NAME!=='videobot')throw Error('OWNER_DB_NOT_VERIFIED');
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,
 database:env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
try{
 const original=(await pool.query("SELECT COUNT(*)::int n FROM videobot_stars_ledger WHERE kind='paid'")).rows[0].n;
 const receipts=(await pool.query("SELECT COUNT(*)::int n FROM videobot_post_receipts WHERE sale_mode='paid_media' AND status='sent'")).rows[0].n;
 const before=(await pool.query("SELECT listing_id,status FROM videobot_listings WHERE listing_id='v26nov24invoice'")).rows;
 const matching=(await pool.query("SELECT COUNT(DISTINCT delivery_key)::int n FROM videobot_stars_ledger WHERE kind='paid' AND delivery_key IS NOT NULL")).rows[0].n;
 if(original<1||receipts<1||matching!==1)throw Error('HISTORIC_RIGHTS_OR_SOURCE_NOT_VERIFIED');
 console.log('BEFORE='+JSON.stringify({paidTransactions:original,previousOffers:receipts,reissue:before}));
}finally{await pool.end()}
NODE
docker exec -w /opt/videobot "$cid" node src/operations/runReissuedVideoInvoice.mjs || exit 43
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
const e=process.env;const p=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,
 database:e.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
try{
 const l=(await p.query("SELECT listing_id,status,price_stars,paid_video_file_id FROM videobot_listings WHERE listing_id='v26nov24invoice'")).rows[0];
 const receipt=(await p.query("SELECT delivery_key,sale_mode,status,free_message_ids,paid_message_id,topic_id FROM videobot_post_receipts WHERE delivery_key='v26nov24invoice:1'")).rows[0];
 const purchased=(await p.query("SELECT COUNT(*)::int n FROM videobot_stars_ledger WHERE kind='paid'")).rows[0].n;
 const entitlements=(await p.query("SELECT COUNT(*)::int n FROM videobot_stars_ledger paid JOIN videobot_listings old ON paid.listing_id=old.listing_id JOIN videobot_listings newer ON old.seller_user_id=newer.seller_user_id AND old.paid_video_file_id=newer.paid_video_file_id WHERE paid.kind='paid' AND newer.listing_id='v26nov24invoice'")).rows[0].n;
 if(!l||l.status!=='published'||!receipt||receipt.status!=='sent'||receipt.sale_mode!=='invoice'||receipt.free_message_ids?.length!==2||!Number.isSafeInteger(Number(receipt.paid_message_id))||entitlements<1)throw Error('VIDEO_REISSUE_LIVE_RECEIPT_OR_BUYER_RIGHTS_UNVERIFIED');
 console.log('AFTER='+JSON.stringify({listing:l.listing_id,status:l.status,stars:l.price_stars,mode:receipt.sale_mode,receipt:receipt.status,freeIds:receipt.free_message_ids.map(Number),purchaseButtonMessage:Number(receipt.paid_message_id),topic:receipt.topic_id,paidTransactions:purchased,eligibleHistoricBuyerTransactions:entitlements}));
}finally{await p.end()}
NODE
